<?php /** Log or change an entry (screens `time-entry-add`, `time-entry-edit`). Data: cur, member, me, date, ws, days, loggable, prefill, activities, settings, here */
$id = $cur['entry_id'] ?? null; $screen = $cur === null ? 'time-entry-add' : 'time-entry-edit'; $inc = (float) $settings['hours_increment'];
$back = ['/time/?week=' . $ws . ($member !== $me ? '&member=' . $member : ''), 'the week']; $selected = $cur['engagement_id'] ?? $prefill; ?>
<?= view('shared/header.php', ['id' => $screen, 'title' => $cur === null ? 'Log time' : 'Change an entry', 'crumbs' => [['Home', '/'], ['My timesheet', '/time/'], [$cur === null ? 'Log' : 'Change', null]], 'back' => back_link() ?? $back]) ?>
<div class="main-content" id="<?= e($screen) ?>-content">
    <?php if ($loggable === []): ?><div class="alert alert-info" id="time-entry-unstaffed">You are staffed on no active engagement on <?= e(format_date($date)) ?>. Ask your manager to staff you.</div><?php endif; ?>
    <form method="post" action="/time/entries/save.php" hx-post="/time/entries/save.php" hx-target="#flash" id="time-entry-form">
        <?= csrf_field() ?><?php if ($id !== null): ?><input type="hidden" name="entry" value="<?= (int) $id ?>"><?php endif; ?><?php if ($member !== $me): ?><input type="hidden" name="member" value="<?= (int) $member ?>"><?php endif; ?><input type="hidden" name="return_to" value="<?= e($back[0]) ?>">
        <div class="card mb-3"><div class="card-body">
            <label class="form-label fs-12 text-muted">Day</label>
            <div class="d-flex gap-1 mb-3 overflow-auto" id="time-entry-form-days"><?php foreach ($days as $d): ?><label class="btn btn-touch <?= $d['date'] === $date ? 'btn-primary' : 'btn-light' ?> flex-fill px-1" for="time-entry-form-field-date-<?= e($d['date']) ?>" style="min-width: 3rem"><input type="radio" class="d-none" name="date" value="<?= e($d['date']) ?>" id="time-entry-form-field-date-<?= e($d['date']) ?>" <?= $d['date'] === $date ? 'checked' : '' ?> onchange="document.querySelectorAll('#time-entry-form-days label').forEach(function (l) { l.classList.remove('btn-primary'); l.classList.add('btn-light'); }); this.parentElement.classList.add('btn-primary'); this.parentElement.classList.remove('btn-light');"><?= e($d['label']) ?></label><?php endforeach; ?></div>
            <label class="form-label fs-12 text-muted" id="time-entry-form-field-engagement-label" for="time-entry-form-field-engagement-open">Engagement</label>
            <?= picker_field(['id' => 'time-entry-form-field-engagement', 'labelledby' => 'time-entry-form-field-engagement-label', 'name' => 'engagement', 'source' => 'engagement_loggable', 'value' => $selected, 'required' => true, 'disabled' => $loggable === [], 'placeholder' => $loggable === [] ? 'None today' : 'Choose the engagement', 'params' => ['member_id' => $member, 'on' => (int) str_replace('-', '', $date)]]) ?>
            <label class="form-label fs-12 text-muted" for="time-entry-form-field-hours">Hours (in steps of <?= e(days_label($inc)) ?>)</label>
            <div class="input-group mb-2" id="time-entry-form-hours">
                <button type="button" class="btn btn-light btn-touch" id="time-entry-form-hours-minus" onclick="var f = document.getElementById('time-entry-form-field-hours'); f.value = Math.max(<?= $inc ?>, (Math.round((parseFloat(f.value) || 0) / <?= $inc ?>) - 1) * <?= $inc ?>).toFixed(2);">−</button>
                <input type="number" name="hours" id="time-entry-form-field-hours" class="form-control btn-touch text-center" inputmode="decimal" step="<?= e(days_label($inc)) ?>" min="<?= e(days_label($inc)) ?>" max="24" required value="<?= e($cur === null ? '' : days_label($cur['hours'])) ?>">
                <button type="button" class="btn btn-light btn-touch" id="time-entry-form-hours-plus" onclick="var f = document.getElementById('time-entry-form-field-hours'); f.value = Math.min(24, (Math.round((parseFloat(f.value) || 0) / <?= $inc ?>) + 1) * <?= $inc ?>).toFixed(2);">+</button>
            </div>
            <div class="d-flex gap-1 mb-3" id="time-entry-form-chips"><?php foreach (HOUR_CHIPS as $c): ?><button type="button" class="btn btn-light btn-sm flex-fill" id="time-entry-form-chip-<?= e(str_replace('.', '_', $c)) ?>" onclick="document.getElementById('time-entry-form-field-hours').value = '<?= e(number_format((float) $c, 2, '.', '')) ?>';"><?= e($c) ?> h</button><?php endforeach; ?></div>
            <label class="form-label fs-12 text-muted" for="time-entry-form-field-activity">Activity</label>
            <select name="activity" id="time-entry-form-field-activity" class="form-select btn-touch mb-3" onchange="var o = this.options[this.selectedIndex]; if (o.dataset.billable !== undefined) { document.getElementById('time-entry-form-field-billable').checked = o.dataset.billable === '1'; }"><option value="">None</option><?php foreach ($activities as $a): ?><option value="<?= (int) $a['id'] ?>" data-billable="<?= $a['billable_default'] ? '1' : '0' ?>" <?= ($cur['activity_type_id'] ?? null) === (int) $a['id'] ? 'selected' : '' ?>><?= e($a['label']) ?></option><?php endforeach; ?></select>
            <input type="hidden" name="billable" value="no">
            <label class="d-flex align-items-center gap-2 border rounded px-3 btn-touch mb-3" for="time-entry-form-field-billable"><input type="checkbox" class="form-check-input mt-0" name="billable" value="yes" id="time-entry-form-field-billable" <?= $cur === null || $cur['billable'] ? 'checked' : '' ?>>Billable (follows the activity's default)</label>
            <label class="form-label fs-12 text-muted" for="time-entry-form-field-note">Note — <strong>the client sees it</strong> on the invoice's detail</label>
            <textarea name="note" id="time-entry-form-field-note" class="form-control mb-3" rows="2" maxlength="1000"><?= e($cur['note'] ?? '') ?></textarea>
            <label class="form-label fs-12 text-muted" for="time-entry-form-field-internal">Internal note (never leaves)</label>
            <textarea name="internal_note" id="time-entry-form-field-internal" class="form-control" rows="2" maxlength="1000"><?= e($cur['internal_note'] ?? '') ?></textarea>
        </div></div>
        <button type="submit" class="btn btn-primary btn-touch w-100 mb-2" id="time-entry-form-save-btn" <?= $loggable === [] ? 'disabled' : '' ?>>Save</button>
        <?php if ($cur === null): ?><button type="submit" name="add_another" value="yes" class="btn btn-light btn-touch w-100 mb-2" id="time-entry-form-save-again-btn" <?= $loggable === [] ? 'disabled' : '' ?>>Save and add another</button><?php endif; ?>
        <?= hx_link($back[0], 'Cancel', 'btn btn-light btn-touch w-100', 'id="time-entry-form-cancel-link"') ?>
    </form>
    <?php if ($cur !== null): ?><form method="post" action="/time/entries/delete.php" hx-post="/time/entries/delete.php" hx-target="#flash" class="mt-2" hx-confirm="Remove this entry?"><?= csrf_field() ?><input type="hidden" name="entry" value="<?= (int) $id ?>"><button type="submit" class="btn btn-light btn-touch w-100 text-danger" id="time-entry-form-delete-btn">Remove the entry</button></form><?php endif; ?>
</div>
